<?php require_once __DIR__.'/../config/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$p=['name'=>'','category_id'=>'','description'=>'','price'=>'','stock'=>0,'image'=>'','active'=>1];if($id){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch()?:$p;}$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$data=[trim($_POST['name']??''),(int)($_POST['category_id']??0)?:null,trim($_POST['description']??''),(float)($_POST['price']??0),(int)($_POST['stock']??0),trim($_POST['image']??'')];if($data[0]===''||$data[3]<0||$data[4]<0){$error='Confira nome, preço e estoque.';}else{if($id){$s=db()->prepare('UPDATE products SET name=?,category_id=?,description=?,price=?,stock=?,image=? WHERE id=?');$s->execute([...$data,$id]);}else{$s=db()->prepare('INSERT INTO products(name,category_id,description,price,stock,image) VALUES(?,?,?,?,?,?)');$s->execute($data);}flash('Produto salvo com sucesso.');redirect('/gamestore/admin/index.php');}}$pageTitle=$id?'Editar produto':'Cadastrar produto';require __DIR__.'/../includes/header.php';?><div class="form-card"><h1 class="h3 fw-bold"><?=e($pageTitle)?></h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label">Nome</label><input class="form-control mb-3" name="name" value="<?=e($p['name'])?>" required><label class="form-label">Categoria</label><select class="form-select mb-3" name="category_id"><option value="">Sem categoria</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label class="form-label">Descrição</label><textarea class="form-control mb-3" name="description" rows="4"><?=e($p['description'])?></textarea><label class="form-label">Preço (R$)</label><input class="form-control mb-3" type="number" step="0.01" min="0" name="price" value="<?=e((string)$p['price'])?>" required><label class="form-label">Estoque</label><input class="form-control mb-3" type="number" min="0" name="stock" value="<?=$p['stock']?>" required><label class="form-label">Endereço da imagem</label><input class="form-control mb-3" name="image" value="<?=e($p['image'])?>"><button class="btn btn-neon w-100">Salvar produto</button></form></div><?php require __DIR__.'/../includes/footer.php';?>
